140:         public AKRSPoint3D BackConvertCoordinate(AKRSPoint3D value)
141:         {
142:             AKRSPoint3D point = new AKRSPoint3D();
143: 
144:             if (this.Type == CoordinateSystemTypeEnum.General)
145:             {
146:                 double distanceX = value.X - this.Distance.X;
147:                 double distanceY = value.Y - this.Distance.Y;
148: 
149:                 double length = Math.Sqrt(distanceX * distanceX + distanceY * distanceY);
150: 
151:                 double degree = Math.Atan2(distanceY, distanceX);
152: 
153:                 point.X = length * Math.Cos(degree - this.Degree);
154:                 point.Y = length * Math.Sin(degree - this.Degree);
155:                 point.Z = value.Z - this.Distance.Z;
156:             }
157:             else if (this.Type == CoordinateSystemTypeEnum.Vm)
158:             {
159:                 throw new InvalidOperationException("不支持海康标定的逆运算");
160:             }
161: 
162:             return point;

