241:         public static AKRSPoint3D GetPoint3D(CCalibTransTool cCalibTransTool, AKRSPoint3D point3D,CalibModuleEnum calibModule, bool invert = false)
242:         {
243:             if (calibModule == CalibModuleEnum.RealisticCoordinateSystem)
244:             {
245:                 MVD_POINT_F resultF = CalculateMvdPointF(cCalibTransTool, point3D, invert);
246: 
247:                 return new AKRSPoint3D(resultF.fX, resultF.fY, 0);
248:             }
249: 
250:             MVD_POINT_F center = CalculateMvdPointF(cCalibTransTool, new AKRSPoint3D(1224, 1024, 0), invert);
251: 
252:             MVD_POINT_F result = CalculateMvdPointF(cCalibTransTool, point3D, invert);
253: 
254:             if (calibModule == CalibModuleEnum.AxisAndCameraIsTogether)
255:             {
256:                 return new AKRSPoint3D(center.fX - result.fX, center.fY - result.fY, 0);
257:             }
258:             else if (calibModule == CalibModuleEnum.CameraStaticUp)
259:             {
260: 
261:                 return new AKRSPoint3D(center.fX - result.fX, center.fY - result.fY, 0);
262:             }
263:             else if (calibModule == CalibModuleEnum.CameraStaticDown)
264:             {
265:                 return new AKRSPoint3D(center.fX - result.fX, center.fY - result.fY, 0);
266:             }
267: 
268:             return null;
269:         }
